    [9, 9, 1, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
]

# Find all non-9 values and their positions
non_9 = {}
for r in range(len(grid)):
    for c in range(len(grid[r])):
        if grid[r][c] != 9:
            if grid[r][c] not in non_9:
                non_9[grid[r][c]] = []
            non_9[grid[r][c]].append((r, c))

print("Non-9 values:")
for color, positions in sorted(non_9.items()):
    print(f"  {color}: {positions}")

# Look for patterns - maybe colors sum to 6?
pairs_same_row_or_col = set()
colors_6 = []
for r in range(len(grid)):
    for c in range(len(grid[r])):
        if grid[r][c] != 9:
            # Check same row
            for c2 in range(len(grid[r])):
                if c2 != c and grid[r][c2] != 9:
                    colors_6.append([grid[r][c], grid[r][c2], 'row', r, c, c2])
            # Check same col
            for r2 in range(len(grid)):
                if r2 != r and grid[r2][c] != 9:
                    colors_6.append([grid[r][c], grid[r2][c], 'col', r, r2, c])

print("\nSame-row/col pairs:")
for p in colors_6:
    print(f"  {p[0]}+{p[1]}={p[0]+p[1]} ({p[2]}, r{p[3]} c{p[4]} & c{p[5]})")

# Look for diagonal patterns
for r in range(len(grid)):
    for c in range(len(grid[r])):
        if grid[r][c] != 9:
            val = grid[r][c]
            # Check main diagonal (down-right)
            d = r - c
            for r2, c2 in [(r+1,c+1), (r+2,c+2), (r-1,c-1), (r-2,c-2)]:
                if 0 <= r2 < len(grid) and 0 <= c2 < len(grid[r2]):
                    if grid[r2][c2] != 9:
                        print(f"{val} and {grid[r2][c2]} on diag d={d}: ({r},{c}) & ({r2},{c2}), sum={val+grid[r2][c2]}")
            # Check anti-diagonal (down-left)
            ad = r + c
            for r2, c2 in [(r+1,c-1), (r+2,c-2), (r-1,c+1), (r-2,c+2)]:
